/**
 * 产品介绍大图轮播（1600×900）
 * 层叠淡入淡出 + 定时轮询；仅指针悬停在画面上时暂停
 * @author 恒哥
 */
import React, { useEffect, useRef, useState } from 'react';
import './product-card-gallery.css';

/**
 * @param {object} props
 * @param {Array<{id:string,src:string,title:string,caption?:string}>} props.cards
 * @param {string} [props.className]
 * @param {number} [props.initialIndex]
 * @param {boolean} [props.autoPlay]
 * @param {number} [props.intervalMs]
 */
export default function ProductCardGallery({
  cards = [],
  className = '',
  initialIndex = 0,
  autoPlay = true,
  intervalMs = 4000,
}) {
  const count = cards.length;
  const [active, setActive] = useState(() =>
    Math.min(Math.max(initialIndex, 0), Math.max(count - 1, 0))
  );
  const pausedRef = useRef(false);
  const touchStartX = useRef(null);
  const progressRef = useRef(null);

  useEffect(() => {
    if (!autoPlay || count < 2) return undefined;

    const tick = () => {
      if (pausedRef.current) return;
      setActive((prev) => (prev + 1) % count);
    };

    const timer = window.setInterval(tick, intervalMs);
    return () => window.clearInterval(timer);
  }, [autoPlay, count, intervalMs]);

  // 进度条重置
  useEffect(() => {
    const el = progressRef.current;
    if (!el || !autoPlay || count < 2) return undefined;
    el.style.transition = 'none';
    el.style.width = '0%';
    // force reflow
    void el.offsetWidth;
    if (!pausedRef.current) {
      el.style.transition = `width ${intervalMs}ms linear`;
      el.style.width = '100%';
    }
    return undefined;
  }, [active, autoPlay, count, intervalMs]);

  if (!count) return null;

  const current = cards[active] || cards[0];

  const goTo = (index) => {
    setActive(((index % count) + count) % count);
  };

  const goNext = () => goTo(active + 1);
  const goPrev = () => goTo(active - 1);

  const setPaused = (value) => {
    pausedRef.current = value;
    const el = progressRef.current;
    if (!el || !autoPlay) return;
    if (value) {
      el.style.transition = 'none';
    }
  };

  return (
    <div className={`product-card-gallery ${className}`.trim()}>
      <div
        className="product-card-gallery-frame"
        onMouseEnter={() => setPaused(true)}
        onMouseLeave={() => {
          setPaused(false);
          // 离开后立刻重启进度动画
          const el = progressRef.current;
          if (el && autoPlay && count > 1) {
            el.style.transition = 'none';
            el.style.width = '0%';
            void el.offsetWidth;
            el.style.transition = `width ${intervalMs}ms linear`;
            el.style.width = '100%';
          }
        }}
        onTouchStart={(e) => {
          touchStartX.current = e.changedTouches[0]?.clientX ?? null;
          setPaused(true);
        }}
        onTouchEnd={(e) => {
          setPaused(false);
          if (touchStartX.current == null) return;
          const dx = (e.changedTouches[0]?.clientX ?? 0) - touchStartX.current;
          touchStartX.current = null;
          if (Math.abs(dx) < 40) return;
          if (dx < 0) goNext();
          else goPrev();
        }}
      >
        {cards.map((card, index) => (
          <img
            key={card.id}
            className={`product-card-gallery-img${index === active ? ' is-active' : ''}`}
            src={card.src}
            alt={card.title}
            width={1600}
            height={900}
            loading={index === 0 ? 'eager' : 'lazy'}
            decoding="async"
            draggable={false}
          />
        ))}

        {count > 1 && (
          <>
            <div className="product-card-gallery-progress" aria-hidden="true">
              <span ref={progressRef} className="product-card-gallery-progress-bar" />
            </div>
            <button
              type="button"
              className="product-card-gallery-nav product-card-gallery-nav-prev"
              aria-label="Previous"
              onClick={goPrev}
            >
              ‹
            </button>
            <button
              type="button"
              className="product-card-gallery-nav product-card-gallery-nav-next"
              aria-label="Next"
              onClick={goNext}
            >
              ›
            </button>
            <div className="product-card-gallery-dots" role="tablist" aria-label="Slides">
              {cards.map((card, index) => (
                <button
                  key={card.id}
                  type="button"
                  role="tab"
                  aria-selected={index === active}
                  aria-label={card.title}
                  className={`product-card-gallery-dot${index === active ? ' is-active' : ''}`}
                  onClick={() => goTo(index)}
                />
              ))}
            </div>
            <span className="product-card-gallery-live" aria-live="polite">
              {active + 1} / {count}
            </span>
          </>
        )}
      </div>

      <p className="product-card-gallery-caption">
        <strong>{current.title}</strong>
        {current.caption ? ` — ${current.caption}` : ''}
      </p>

      {count > 1 && (
        <div className="product-card-gallery-tabs" role="tablist" aria-label="Product overview cards">
          {cards.map((card, index) => (
            <button
              key={card.id}
              type="button"
              role="tab"
              aria-selected={index === active}
              className={`product-card-gallery-tab${index === active ? ' is-active' : ''}`}
              onClick={() => goTo(index)}
            >
              {card.title}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
